-- ─── 1. Pre-gates ───────────────────────────────────────────────────────────────
DO $$
DECLARE v_n integer; v_bad text;
BEGIN
  -- gate 0: the prior text recorded in THIS FILE must be the text its hash claims.
  SELECT string_agg(rc_id::text, ', ') INTO v_bad
    FROM cc0409_rows WHERE md5(prior_source) <> prior_md5;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'CC_0409 gate: the prior value recorded in this file does not hash to its recorded md5 for %', v_bad;
  END IF;

  SELECT count(*) INTO v_n FROM cc0409_rows;
  IF v_n <> 43 THEN RAISE EXCEPTION 'CC_0409 gate: % rows in the payload, expected 43', v_n; END IF;

  -- gate 1: production must still hold exactly that text, or somebody has edited it since.
  SELECT string_agg(t.rc_id::text, ', ') INTO v_bad
    FROM cc0409_rows t JOIN essentials.race_candidates rc ON rc.id = t.rc_id
   WHERE md5(rc.result_source) <> t.prior_md5;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'CC_0409 gate: result_source has changed since this file was written, for %', v_bad;
  END IF;

  -- gate 2: every target must currently BE a member of the class this file exists to clear.
  SELECT count(*) INTO v_n
    FROM cc0409_rows t JOIN essentials.race_candidates rc ON rc.id = t.rc_id
   WHERE rc.result_source ~ '[^0-9,]0 votes, 0(\.0+)?%';
  IF v_n <> 43 THEN RAISE EXCEPTION 'CC_0409 gate: only % of 43 targets carry the zero-vote sentence', v_n; END IF;

  -- gate 3: every target must be a recorded WINNER whose call is AP's, not a canvass.
  SELECT count(*) INTO v_n
    FROM cc0409_rows t JOIN essentials.race_candidates rc ON rc.id = t.rc_id
   WHERE rc.result = 'won' AND rc.result_certainty = 'called';
  IF v_n <> 43 THEN RAISE EXCEPTION 'CC_0409 gate: % of 43 targets are won/called; this file corrects a citation, not a result', v_n; END IF;

  -- gate 4: "not false" is not "true" — the state's own number must be IN each new citation.
  SELECT string_agg(rc_id::text, ', ') INTO v_bad
    FROM cc0409_rows
   WHERE position(to_char(state_votes, 'FM999,999,999') IN new_source) = 0;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'CC_0409 gate: the state''s count is not in the new citation for %', v_bad;
  END IF;

  -- gate 5: 🔴 the replacement must not re-state the sentence it corrects, or the row stays in
  -- the class, the remaining-count below becomes a lie, and every later sweep re-finds this row.
  SELECT string_agg(rc_id::text, ', ') INTO v_bad
    FROM cc0409_rows WHERE new_source ~ '[^0-9,]0 votes, 0(\.0+)?%';
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'CC_0409 gate: the zero-vote sentence is still on the replacement for %', v_bad;
  END IF;

  -- gate 6: provenance for the CALL must survive the rewrite.
  SELECT string_agg(rc_id::text, ', ') INTO v_bad
    FROM cc0409_rows WHERE new_source NOT LIKE '%AP race 20261103%';
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'CC_0409 gate: the new citation dropped the AP race id for %', v_bad;
  END IF;
END $$;

-- Snapshot everything this file must NOT move.
CREATE TEMP TABLE cc0409_before AS
  SELECT rc.id, rc.result, rc.result_certainty, rc.result_recorded_at
    FROM essentials.race_candidates rc JOIN cc0409_rows t ON t.rc_id = rc.id;
CREATE TEMP TABLE cc0409_counts AS
  SELECT (SELECT count(*) FROM essentials.office_terms) AS terms,
         -- 🔴 THIS GATE IS VACUOUS AND IS LEFT HERE AS WRITTEN, BECAUSE IT IS WHAT RAN.
         -- The election id below is INDIANA's, copied from CC_0408 which was an Indiana-only
         -- file. This migration touches WA, AZ, UT, CA, CO and OR and no Indiana row at all, so
         -- the count was 0 before and 0 after and the comparison could never have failed —
         -- "count(*) = 0 passes vacuously", the exact shape CLAUDE.md warns about. Measured
         -- after applying: the only 6 certified rows dated 2026-11-03 belong to the SC 2026
         -- Statewide General, which this file does not touch either.
         -- What actually protects the result is the PER-ROW comparison against cc0409_before
         -- below, which is row-scoped and not vacuous; control V7 (a tamper that sets every
         -- touched row to 'certified') fails on that check, not on this one.
         -- Not rewritten: a migration is applied once by hand and is never replayed, so a
         -- corrected gate here would claim a check that never ran. The comment is the fix.
         (SELECT count(*) FROM essentials.race_candidates rc
            JOIN essentials.races r ON r.id = rc.race_id
           WHERE r.election_id = '21190350-91e3-4c2c-938d-9cf8f4ac9d5c'::uuid
             AND rc.result_certainty = 'certified') AS certified_general,
         (SELECT count(*) FROM essentials.race_candidates
           WHERE result_source ~ '[^0-9,]0 votes, 0(\.0+)?%') AS zero_vote_rows;

-- ─── 2. The write ───────────────────────────────────────────────────────────────
UPDATE essentials.race_candidates rc
   SET result_source = t.new_source
  FROM cc0409_rows t
 WHERE rc.id = t.rc_id
   AND md5(rc.result_source) = t.prior_md5;

-- ─── 3. Post-verify ─────────────────────────────────────────────────────────────
DO $$
DECLARE v_n integer; v_was integer; v_bad text;
BEGIN
  -- Every target now carries its state's number and none carries the old sentence.
  SELECT count(*) INTO v_n
    FROM cc0409_rows t JOIN essentials.race_candidates rc ON rc.id = t.rc_id
   WHERE rc.result_source = t.new_source;
  IF v_n <> 43 THEN RAISE EXCEPTION 'CC_0409 post: % of 43 rows carry their new citation', v_n; END IF;

  -- 🔴 The class must fall by exactly the 43 touched, to exactly the 11 this pass cannot source.
  SELECT count(*) INTO v_n FROM essentials.race_candidates
   WHERE result_source ~ '[^0-9,]0 votes, 0(\.0+)?%';
  SELECT zero_vote_rows INTO v_was FROM cc0409_counts;
  IF v_was <> 54 THEN RAISE EXCEPTION 'CC_0409 post: the class held % rows before this file, expected 54', v_was; END IF;
  IF v_n <> 11 THEN
    RAISE EXCEPTION 'CC_0409 post: % rows still carry the zero-vote sentence, expected 11 (WI 8 + MA 3, which have no state return)', v_n;
  END IF;

  -- Nothing about the RESULT may have moved. The call is AP's and stays where it was.
  SELECT string_agg(b.id::text, ', ') INTO v_bad
    FROM cc0409_before b JOIN essentials.race_candidates rc ON rc.id = b.id
   WHERE rc.result IS DISTINCT FROM b.result
      OR rc.result_certainty IS DISTINCT FROM b.result_certainty;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'CC_0409 post: the result moved on %', v_bad; END IF;

  SELECT string_agg(b.id::text, ', ') INTO v_bad
    FROM cc0409_before b JOIN essentials.race_candidates rc ON rc.id = b.id
   WHERE rc.result_recorded_at IS DISTINCT FROM b.result_recorded_at;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'CC_0409 post: result_recorded_at moved on % — this file records no new result', v_bad;
  END IF;

  -- This file seats nobody and certifies nothing.
  SELECT count(*) INTO v_n FROM essentials.office_terms;
  IF v_n <> (SELECT terms FROM cc0409_counts) THEN
    RAISE EXCEPTION 'CC_0409 post: office_terms moved from % to %', (SELECT terms FROM cc0409_counts), v_n;
  END IF;
  SELECT count(*) INTO v_n FROM essentials.race_candidates rc
    JOIN essentials.races r ON r.id = rc.race_id
   WHERE r.election_id = '21190350-91e3-4c2c-938d-9cf8f4ac9d5c'::uuid
     AND rc.result_certainty = 'certified';
  IF v_n <> (SELECT certified_general FROM cc0409_counts) THEN
    RAISE EXCEPTION 'CC_0409 post: certified rows in the 2026-11-03 general moved from % to %',
      (SELECT certified_general FROM cc0409_counts), v_n;
  END IF;
END $$;

DROP TABLE IF EXISTS cc0409_before;
DROP TABLE IF EXISTS cc0409_counts;

COMMIT;
